mapper.select:
select , cu.nick_name as create_user_name,
       (select coalesce(sum(d.qty), 0) from sdsorder.u_f_shipbatchdetail_${tableSuffix} d
         where d.shop_code = b.shop_code and d.shipcode = b.shipcode) as total_qty
  from sdsorder.u_f_shipbatch_${tableSuffix} b
  left join sys_user cu on cu.user_name = b.createuser
 where b.shop_code = #{query.shopCode}
 and b.shipcode like concat('%', #{query.shipCode}, '%')
 and b.ordercode = #{query.orderCode}
 and b.status = #{query.status}

 and b.status in ('已提交仓库', '已打印备货单', '备货完成', '已录入快递单号', '已打印快递单号', '已完成')

 and b.createuser = #{query.ownerScope}
 and b.warehousecode = #{query.warehouseCode}
 and b.logisticsno = #{query.logisticsNo}
 order by b.shipdate desc, b.createtime desc

select 
  from sdsorder.u_f_shipbatch_${tableSuffix}
 where shop_code = #{shopCode} and shipcode = #{shipCode}
 for update

mapper.update:
update sdsorder.u_f_shipbatch_${tableSuffix}
   set status = #{status},


       confirmuser = #{operator}, confirmtime = #{operateTime},



       shipuser = #{operator}, shiptime = #{operateTime}, actualshiptime = #{operateTime},


       updatetime = sysdate()
 where shop_code = #{shopCode} and shipcode = #{shipCode}
 and status = #{expectedStatus}

update sdsorder.u_f_shipbatch_${tableSuffix}
   set pickphotos = #{photos},
       updatetime = sysdate()
 where shop_code = #{shopCode} and shipcode = #{shipCode}
   and status in ('已打印备货单', '备货完成')
